-- Additive employee authorization storage. Parent identity types are preserved.
SET @foon_staff_tenant_type = (SELECT CONCAT(COLUMN_TYPE,' CHARACTER SET ',CHARACTER_SET_NAME,' COLLATE ',COLLATION_NAME) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tenants' AND COLUMN_NAME='id' AND DATA_TYPE IN ('char','varchar') AND CHARACTER_MAXIMUM_LENGTH>=36);
SET @foon_staff_user_type = (SELECT CONCAT(COLUMN_TYPE,' CHARACTER SET ',CHARACTER_SET_NAME,' COLLATE ',COLLATION_NAME) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='users' AND COLUMN_NAME='id' AND DATA_TYPE IN ('char','varchar') AND CHARACTER_MAXIMUM_LENGTH>=36);
SET @foon_staff_branch_type = (SELECT CONCAT(COLUMN_TYPE,' CHARACTER SET ',CHARACTER_SET_NAME,' COLLATE ',COLLATION_NAME) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='branches' AND COLUMN_NAME='id' AND DATA_TYPE IN ('char','varchar') AND CHARACTER_MAXIMUM_LENGTH>=36);
SET @foon_staff_sql = CONCAT('CREATE TABLE IF NOT EXISTS employee_branch_assignments (id VARCHAR(36) NOT NULL PRIMARY KEY, tenant_id ',@foon_staff_tenant_type,' NOT NULL, user_id ',@foon_staff_user_type,' NOT NULL, branch_id ',@foon_staff_branch_type,' NOT NULL, role VARCHAR(40) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY employee_branch_scope (tenant_id,user_id,branch_id), FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_staff_assignment_branch FOREIGN KEY (tenant_id,branch_id) REFERENCES branches(tenant_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
PREPARE foon_staff_statement FROM @foon_staff_sql;
EXECUTE foon_staff_statement;
DEALLOCATE PREPARE foon_staff_statement;
SET @foon_staff_sql = CONCAT('CREATE TABLE IF NOT EXISTS employee_permission_grants (id VARCHAR(36) NOT NULL PRIMARY KEY, tenant_id ',@foon_staff_tenant_type,' NOT NULL, user_id ',@foon_staff_user_type,' NOT NULL, branch_id ',@foon_staff_branch_type,' NULL, permission_key VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, allowed BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY employee_permission_scope (tenant_id,user_id,branch_id), FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_staff_permission_branch FOREIGN KEY (tenant_id,branch_id) REFERENCES branches(tenant_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
PREPARE foon_staff_statement FROM @foon_staff_sql;
EXECUTE foon_staff_statement;
DEALLOCATE PREPARE foon_staff_statement;
